        while end < h and grid[end] == grid[r]:
            end += 1
        seq = [v for v in grid[r] if v]
        if end - r >= 2 and len(seq) >= 2:
            if best is None or end - r > best[0]:
                best = (end - r, r, end, seq)
        r = end

