    def shape(coords):
        top = min(y for y, x in coords)
        left = min(x for y, x in coords)
        mask = frozenset((y - top, x - left) for y, x in coords)
        height = max(y for y, x in coords) - top + 1
        width = max(x for y, x in coords) - left + 1
        return top, left, height, width, mask

    candidates = [(c, shape(coords)) for c, coords in groups.items()
                  if c in colors]
    if not candidates:
        return [row[:] for row in grid]

    # Use the repeated silhouette shared by the existing colored layers.
    chosen_color, chosen = max(candidates, key=lambda item: len(groups[item[0]]))
